/*
 * As revisões de um artigo da linkrobins/wiki no mesmo modal do histórico de
 * edições dos posts (features/extras/history): a lista das revisões ao lado
 * (no celular, uma faixa no topo), ‹ › para andar entre elas, quem editou e
 * quando, e o diff por palavras do markdown, no texto ou lado a lado.
 *
 * Os dados são os que a wiki já usa no painel dela: o índice
 * `linkrobins-wiki-revisions` filtrado pelo artigo (da mais nova para a mais
 * antiga, 100 por página). Aqui a ordem vira a do modal (da mais antiga para
 * a mais nova), e o título e o resumo da revisão entram por cima do diff.
 */
import app from 'flarum/forum/app';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Avatar from 'flarum/common/components/Avatar';
import Icon from 'flarum/common/components/Icon';
import classList from 'flarum/common/utils/classList';
import HistoryModal from '../../features/extras/history/HistoryModal';
import { fullDate, shortAge } from '../../utils/dates';
import { t } from '../../utils/settings';
import { wt } from './shared';
/** O teto da wiki por página; menos que isso, acabou. */
const PAGE = 100;
/** Até 1000 revisões: mais que isso só num artigo editado por robô. */
const MAX_PAGES = 10;
const wtr = (key, params = {}) => t(`thirdparty.wiki.${key}`, params);
function fetchPage(articleId, offset) {
  return app.store.find('linkrobins-wiki-revisions', {
    sort: '-createdAt',
    filter: {
      articleId
    },
    page: {
      limit: PAGE,
      offset
    },
    include: 'user',
    fields: {
      'linkrobins-wiki-revisions': 'title,content,summary,createdAt,user'
    }
  }).then(list => Array.isArray(list) ? list : []);
}
async function fetchAll(articleId) {
  const all = [];
  for (let page = 0; page < MAX_PAGES; page++) {
    const items = await fetchPage(articleId, all.length);
    all.push(...items);
    if (items.length < PAGE) break;
  }
  return all;
}
function toDate(value) {
  if (!value) return null;
  const date = value instanceof Date ? value : new Date(String(value));
  return Number.isNaN(date.getTime()) ? null : date;
}
export default class WikiRevisionsModal extends HistoryModal {
  /** As versões com os campos da wiki (título, resumo e o modelo da revisão). */
  wikiVersions() {
    return this.versions;
  }
  load() {
    const article = this.attrs.article;
    return fetchAll(String(article.id())).then(newestFirst => {
      const versions = newestFirst.slice().reverse().map((rev, index) => {
        const user = rev.user?.() || null;
        const created = toDate(rev.createdAt?.());
        return {
          number: index + 1,
          createdAt: created ? created.toISOString() : null,
          user: user ? {
            id: String(user.id()),
            username: user.username(),
            displayName: user.displayName(),
            avatarUrl: user.avatarUrl() || null
          } : null,
          content: rev.content?.() ?? '',
          title: rev.title?.() ?? '',
          summary: rev.summary?.() ?? '',
          model: rev
        };
      });
      return {
        versions,
        contentHidden: false
      };
    });
  }
  className() {
    return 'CanelaHistoryModal CanelaWikiRevisionsModal Modal--large';
  }
  title() {
    return wtr('history_title');
  }
  content() {
    if (this.loading) return m("div", {
      className: "Modal-body"
    }, m(LoadingIndicator, null));
    if (this.failed || !this.versions.length) {
      return m("div", {
        className: "Modal-body"
      }, m("p", {
        className: "CanelaHistory-empty"
      }, this.failed ? wtr('history_failed') : wt('show.no_history', 'No revisions yet.')));
    }
    return m("div", {
      className: "Modal-body CanelaHistory CanelaWikiRevisions"
    }, this.revisionList(), m("div", {
      className: "CanelaWikiRevisions-main"
    }, this.navigation(), this.comparison()));
  }

  /** A lista ao lado, da mais nova para a mais antiga, como no painel da wiki. */
  revisionList() {
    const items = this.wikiVersions().map((version, index) => ({
      version,
      index
    })).reverse();
    return m("ol", {
      className: "CanelaWikiRevisions-list",
      "aria-label": wtr('history_title')
    }, items.map(({
      version,
      index
    }) => {
      const user = version.model?.user?.() || null;
      const date = toDate(version.createdAt);
      const active = index === this.index;
      return m("li", {
        key: `rev-${version.number}`
      }, m("button", {
        type: "button",
        className: classList('Button--ua-reset CanelaWikiRevisions-item', {
          active
        }),
        "aria-current": active ? 'true' : undefined,
        title: date ? fullDate(date) : undefined,
        onclick: () => this.index = index
      }, user ? m(Avatar, {
        user: user,
        className: "CanelaWikiRevisions-avatar"
      }) : m(Icon, {
        name: "fas fa-user-pen"
      }), m("span", {
        className: "CanelaWikiRevisions-info"
      }, m("span", {
        className: "CanelaWikiRevisions-line"
      }, m("span", {
        className: "CanelaWikiRevisions-number"
      }, `#${version.number}`), m("span", {
        className: "CanelaWikiRevisions-user"
      }, version.user ? version.user.displayName : t('extras.history.deleted_user'))), m("span", {
        className: "CanelaWikiRevisions-meta"
      }, index === 0 ? m("span", {
        className: "CanelaWikiTag"
      }, wt('show.initial_version', 'created')) : null, version.summary ? m("span", {
        className: "CanelaWikiRevisions-summary"
      }, version.summary) : null)), m("span", {
        className: "CanelaWikiRevisions-date"
      }, shortAge(date))));
    }));
  }

  /** O resumo e a troca de título da revisão vêm antes do diff do texto. */
  comparison() {
    const versions = this.wikiVersions();
    const current = versions[this.index];
    const previous = this.index > 0 ? versions[this.index - 1] : null;
    const titleChanged = !!previous && previous.title !== current.title;
    return [current.summary ? m("p", {
      className: "CanelaWikiRevisions-note"
    }, m(Icon, {
      name: "fas fa-quote-left"
    }), m("span", null, current.summary)) : null, titleChanged ? m("p", {
      className: "CanelaWikiRevisions-title"
    }, m("span", {
      className: "CanelaWikiRevisions-titleLabel"
    }, wt('show.diff_title', 'Title')), m("del", {
      className: "CanelaHistory-del"
    }, previous.title), m(Icon, {
      name: "fas fa-arrow-right"
    }), m("ins", {
      className: "CanelaHistory-ins"
    }, current.title)) : null, previous && previous.content === current.content ? m("p", {
      className: "CanelaHistory-empty"
    }, wt('show.diff_none', 'No content changes.')) : super.comparison()];
  }
}
flarum.reg.add('ramon-canela', 'forum/thirdparty/wiki/WikiRevisionsModal', WikiRevisionsModal);